public class WebRtcReplay {
 static int findCodecIndex(){MediaCodecInfo[] a=new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos();for(int i=0;i<a.length;i++)if(a[i].getName().equals("c2.unisoc.avc.decoder"))return i;throw new IllegalStateException("CODEC_MISSING");}
 static long now(){return SystemClock.elapsedRealtimeNanos();}
 static class Sample{byte[] data;long pts;boolean key;Sample(byte[]d,long p,boolean k){data=d;pts=p;key=k;}}
 static byte[] bytes(ByteBuffer b){byte[] a=new byte[b.remaining()];b.duplicate().get(a);return a;}
 static byte[] annex(byte[] a)throws Exception{if(a.length>=4&&a[0]==0&&a[1]==0&&(a[2]==1||(a[2]==0&&a[3]==1)))return a;ByteArrayOutputStream b=new ByteArrayOutputStream();for(int i=0;i<a.length;){if(i+4>a.length)throw new Exception("TRUNCATED_AVCC");int n=ByteBuffer.wrap(a,i,4).getInt();i+=4;if(n<1||i+n>a.length)throw new Exception("AVCC_LENGTH");b.write(new byte[]{0,0,0,1});b.write(a,i,n);i+=n;}return b.toByteArray();}
 static List<Sample> samples(String file)throws Exception{if(file.endsWith(".cgr")){byte[] raw=java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(file));ByteBuffer b=ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);List<Sample>s=new ArrayList<>();long first=-1;while(b.hasRemaining()){if(b.remaining()<20)throw new Exception("TRUNCATED_HEADER");int size=b.getInt();long rtp=Integer.toUnsignedLong(b.getInt());b.getLong();boolean idr=b.getInt()!=0;if(size<1||size>b.remaining())throw new Exception("TRUNCATED_FRAME");byte[] data=new byte[size];b.get(data);if(first<0){first=rtp;if(!idr)throw new Exception("MISSING_IDR");}long pts=((rtp-first)&0xffffffffL)*1000000L/90000L;s.add(new Sample(data,pts,idr));}return s;}MediaExtractor ex=new MediaExtractor();ex.setDataSource(file);ex.selectTrack(0);MediaFormat fmt=ex.getTrackFormat(0);ByteArrayOutputStream csd=new ByteArrayOutputStream();for(int i=0;fmt.containsKey("csd-"+i);i++)csd.write(annex(bytes(fmt.getByteBuffer("csd-"+i))));List<Sample> s=new ArrayList<>();ByteBuffer b=ByteBuffer.allocate(2*1024*1024);for(;;){b.clear();int n=ex.readSampleData(b,0);if(n<0)break;byte[]a=new byte[n];b.get(a);boolean key=(ex.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0;ByteArrayOutputStream f=new ByteArrayOutputStream();if(key)f.write(csd.toByteArray());f.write(annex(a));s.add(new Sample(f.toByteArray(),ex.getSampleTime(),key));ex.advance();}ex.release();return s;}
 static byte[] parameterSet(byte[] data,int type){for(int i=0;i+4<data.length;i++){int n=0;if(data[i]==0&&data[i+1]==0&&data[i+2]==1)n=3;else if(data[i]==0&&data[i+1]==0&&data[i+2]==0&&data[i+3]==1)n=4;if(n==0)continue;int end=data.length;for(int j=i+n;j+3<data.length;j++)if(data[j]==0&&data[j+1]==0&&(data[j+2]==1||(data[j+2]==0&&data[j+3]==1))){end=j;break;}if((data[i+n]&31)==type)return Arrays.copyOfRange(data,i,end);i=end-1;}throw new IllegalArgumentException("PARAMETER_SET_MISSING");}
 static JSONObject run(List<Sample>s,String mode,int gap,int rep)throws Exception{
  JSONObject result=new JSONObject();result.put("mode",mode);result.put("gapMs",gap);result.put("rep",rep);List<JSONObject> inputs=Collections.synchronizedList(new ArrayList<>()),outputs=Collections.synchronizedList(new ArrayList<>()),codecOutputs=Collections.synchronizedList(new ArrayList<>());ConcurrentHashMap<Long,Long> inTimes=new ConcurrentHashMap<>();EglBase egl=null;VideoDecoder decoder=null;
  try{egl=EglBase.create();MediaCodecWrapperFactory factory=name->{MediaCodecWrapper delegate=new MediaCodecWrapperFactoryImpl().createByCodecName(name);return (MediaCodecWrapper)Proxy.newProxyInstance(MediaCodecWrapper.class.getClassLoader(),new Class[]{MediaCodecWrapper.class},(proxy,m,a)->{if(m.getName().equals("configure")){MediaFormat f=(MediaFormat)a[0];if(mode.equals("low"))f.setInteger("low-latency",1);if(mode.equals("fps"))f.setInteger("frame-rate",30);if(mode.equals("csd")){f.setByteBuffer("csd-0",ByteBuffer.wrap(parameterSet(s.get(0).data,7)));f.setByteBuffer("csd-1",ByteBuffer.wrap(parameterSet(s.get(0).data,8)));}if(mode.equals("priority"))f.setInteger("priority",0);result.put("configured",f.toString());}try{Object ret=m.invoke(delegate,a);if(m.getName().equals("dequeueOutputBuffer")&&((Integer)ret)>=0){MediaCodec.BufferInfo bi=(MediaCodec.BufferInfo)a[0];Long start=inTimes.get(bi.presentationTimeUs);codecOutputs.add(new JSONObject().put("atNs",now()).put("ptsUs",bi.presentationTimeUs).put("residenceMs",start==null?JSONObject.NULL:(now()-start)/1e6));}return ret;}catch(InvocationTargetException ex){throw ex.getCause();}});};decoder=new AndroidVideoDecoder(factory,"c2.unisoc.avc.decoder",VideoCodecMimeType.H264,MediaCodecUtils.selectColorFormat(MediaCodecUtils.DECODER_COLOR_FORMATS,new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos()[findCodecIndex()].getCapabilitiesForType("video/avc")),egl.getEglBaseContext());VideoCodecStatus init=decoder.initDecode(new VideoDecoder.Settings(4,720,1570),(frame,decodeTime,qp)->{try{long at=now(),pts=frame.getTimestampNs()/1000L;Long start=inTimes.get(pts);outputs.add(new JSONObject().put("atNs",at).put("ptsUs",pts).put("decodeTimeMs",decodeTime==null?JSONObject.NULL:decodeTime).put("residenceMs",start==null?JSONObject.NULL:(at-start)/1e6));}catch(Exception e){throw new RuntimeException(e);}});result.put("init",init.toString());if(init!=VideoCodecStatus.OK)throw new Exception("INIT_FAILED");long start=now();for(int idx=0;idx<s.size();idx++){long due=start+idx*33_333_333L+(idx>=30?gap*1_000_000L:0);while(now()<due)Thread.sleep(1);Sample sample=s.get(idx);ByteBuffer b=ByteBuffer.allocateDirect(sample.data.length);b.put(sample.data).flip();EncodedImage image=EncodedImage.builder().setBuffer(b,()->{}).setEncodedWidth(720).setEncodedHeight(1570).setCaptureTimeNs(sample.pts*1000).setFrameType(sample.key?EncodedImage.FrameType.VideoFrameKey:EncodedImage.FrameType.VideoFrameDelta).createEncodedImage();long at=now();inTimes.put(sample.pts,at);VideoCodecStatus status=decoder.decode(image,new VideoDecoder.DecodeInfo(false,0));inputs.add(new JSONObject().put("index",idx).put("atNs",at).put("ptsUs",sample.pts).put("status",status.toString()).put("callMs",(now()-at)/1e6));image.release();}Thread.sleep(450);result.put("release",decoder.release().toString());decoder=null;
  }catch(Exception e){result.put("error",e.getClass().getName()+":"+e.getMessage());}finally{if(decoder!=null)decoder.release();if(egl!=null)egl.release();}result.put("inputs",new JSONArray(inputs));result.put("outputs",new JSONArray(outputs));result.put("codecOutputs",new JSONArray(codecOutputs));return result;
 }
 public static void main(String[]args)throws Exception{
  if(Looper.myLooper()==null)Looper.prepare();Class<?> a=Class.forName("android.app.ActivityThread");Object thread=a.getMethod("systemMain").invoke(null);android.content.Context ctx=(android.content.Context)a.getMethod("getSystemContext").invoke(thread);ContextUtils.initialize(ctx);NativeLibrary.initialize(name->{System.load(args[2]);return true;},"jingle_peerconnection_so");List<Sample>s=samples(args[0]);JSONObject r=new JSONObject().put("samples",s.size()).put("scope","actual SDK AndroidVideoDecoder same exact codec; synthetic local input under shell UID");JSONArray runs=new JSONArray();r.put("runs",runs);for(int rep=0;rep<2;rep++)for(int gap:new int[]{0,300})for(String mode:args.length>3?args[3].split(","):new String[]{"default","low","fps","priority"}){runs.put(run(s,mode,gap,rep));try(FileWriter f=new FileWriter(args[1])){f.write(r.toString());}}System.out.println(new JSONObject().put("finished",true).put("runs",runs.length()).toString());
 }
}
